import ollama from "ollama";
import { z } from "zod";

export const MODEL = process.env.OLLAMA_MODEL ?? "gemma3:4b";

// What Gemma must return for every message Maa sends.
export const Intent = z.object({
  intent: z.enum([
    "meal_done", // "khana kha liya"
    "vitamin_taken", // "le li", "kha li goli"
    "snooze", // "baad mein lungi", "10 min ruko"
    "skip", // "aaj nahi lena"
    "other", // greetings, questions, anything else
  ]),
  meal: z.enum(["breakfast", "lunch", "dinner", "unknown"]).nullable(),
  snooze_minutes: z.number().int().nullable(),
  reply: z.string(), // short warm reply in the same language she used
});
export type Intent = z.infer<typeof Intent>;

const SYSTEM = `You are "Dawai Dost", a gentle helper that reminds an Indian mother to take her multivitamin after meals.
She writes in Hindi, Hinglish (Hindi in Latin script) or simple English, often with typos.

Classify her message:
- meal_done: she has just eaten (breakfast/nashta, lunch/dopahar ka khana, dinner/raat ka khana).
- vitamin_taken: she has taken the vitamin/tablet/goli/dawai.
- snooze: she will take it later. Put the delay in snooze_minutes if she says one, else null.
- skip: she will not take it today.
- other: anything else.

If both eating and taking the vitamin are mentioned, choose vitamin_taken.
meal: which meal she means if you can tell from words or the current time, else "unknown". Null if not about a meal.
reply: one short, warm, respectful sentence in the SAME language and script she used. Call her "Maa". No lecturing.`;

export async function parseMessage(text: string, now = new Date()): Promise<Intent> {
  const time = now.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Kolkata" });
  const res = await ollama.chat({
    model: MODEL,
    messages: [
      { role: "system", content: SYSTEM },
      { role: "user", content: `Current time: ${time}\nMessage: ${text}` },
    ],
    format: z.toJSONSchema(Intent),
    options: { temperature: 0 },
  });
  return Intent.parse(JSON.parse(res.message.content));
}

// Run: pnpm test:hinglish
// Checks whether Gemma understands the kind of messages Maa actually sends.
// Replace these with her real messages once you have them.
import { parseMessage, MODEL } from "../src/intent.ts";

const cases: { text: string; at: string; expect: string }[] = [
  { text: "haan beta khana kha liya", at: "13:30", expect: "meal_done" },
  { text: "abhi nashta kiya", at: "09:00", expect: "meal_done" },
  { text: "le li goli", at: "13:50", expect: "vitamin_taken" },
  { text: "vitamin kha li", at: "21:15", expect: "vitamin_taken" },
  { text: "baad mein lungi", at: "14:00", expect: "snooze" },
  { text: "10 min ruko pehle bartan dho lu", at: "14:00", expect: "snooze" },
  { text: "aaj nahi lena, pet kharab hai", at: "20:30", expect: "skip" },
  { text: "खाना खा लिया", at: "20:45", expect: "meal_done" },
  { text: "dinner ke baad tablet bhi le li", at: "21:30", expect: "vitamin_taken" },
  { text: "tum kab aa rahi ho ghar?", at: "18:00", expect: "other" },
];

let pass = 0;
console.log(`Model: ${MODEL}\n`);
for (const c of cases) {
  const [h, m] = c.at.split(":").map(Number);
  const now = new Date();
  now.setUTCHours(h - 5, m - 30); // IST -> UTC
  const t0 = Date.now();
  const r = await parseMessage(c.text, now);
  const ok = r.intent === c.expect;
  if (ok) pass++;
  console.log(
    `${ok ? "✅" : "❌"} [${c.at}] "${c.text}"\n   → ${r.intent}` +
      (r.meal ? ` (${r.meal})` : "") +
      (r.snooze_minutes ? ` snooze=${r.snooze_minutes}m` : "") +
      `${ok ? "" : `  (expected ${c.expect})`}  ${Date.now() - t0}ms\n   reply: ${r.reply}\n`,
  );
}
console.log(`${pass}/${cases.length} correct`);

