// Everything about mummy's routine lives here, read from .env.
try {
  process.loadEnvFile();
} catch {
  // no .env file; fall back to defaults / real environment
}

export const MEALS = ["breakfast", "lunch", "dinner"] as const;
export type Meal = (typeof MEALS)[number];

const digits = (s = "") => s.replace(/\D/g, "");

// "breakfast=10:30,lunch=14:30" -> { breakfast: [10, 30], lunch: [14, 30] }
function parseCheckIns(s: string): Partial<Record<Meal, [number, number]>> {
  const out: Partial<Record<Meal, [number, number]>> = {};
  for (const part of s.split(",")) {
    const [meal, hm] = part.trim().split("=");
    if (MEALS.includes(meal as Meal) && hm) out[meal as Meal] = hm.split(":").map(Number) as [number, number];
  }
  return out;
}

const env = process.env;

export const config = {
  // WhatsApp numbers with country code, e.g. 919876543210
  mummyNumber: digits(env.MUMMY_NUMBER),
  alertNumber: digits(env.ALERT_NUMBER), // you: gets told when a dose is missed or skipped

  // Which meals she takes the vitamin after
  vitaminMeals: (env.VITAMIN_MEALS ?? "lunch").split(",").map((m) => m.trim()) as Meal[],

  // If she hasn't said anything by this time, ask her
  checkIns: parseCheckIns(env.CHECKINS ?? "breakfast=10:30,lunch=14:30,dinner=21:30"),

  remindAfterMin: Number(env.REMIND_AFTER_MIN ?? 15), // after she says she has eaten
  followUpMin: Number(env.FOLLOW_UP_MIN ?? 20), // gap between nudges
  maxReminders: Number(env.MAX_REMINDERS ?? 3), // then alert you instead of nagging her
};

// Every message mummy receives is written here by hand, not by the model.
// Gemma only decides *which* one to send.
import type { Meal } from "./config.ts";

const mealName: Record<Meal, string> = { breakfast: "nashta", lunch: "lunch", dinner: "dinner" };

export const say = {
  checkIn: (meal: Meal) => `Mummy, ${mealName[meal]} ho gaya? Ho gaya ho to vitamin le lijiye 💊`,
  willRemind: (min: number) => `Theek hai mummy, ${min} minute mein vitamin yaad dilaungi 💊`,
  remind: "Mummy, vitamin le lijiye 💊",
  followUp: 'Mummy, vitamin li? 🙂 Le li ho to "le li" likh dijiye',
  taken: "Shabaash mummy! 💊❤️",
  alreadyTaken: "Aaj ki vitamin to ho gayi mummy 👍",
  snoozed: (min: number) => `Theek hai, ${min} minute baad yaad dilaungi`,
  skipped: "Theek hai mummy, apna dhyan rakhna 🙏",

  // to you
  alertMissed: (meal: Meal, n: number) =>
    `Reme: mummy ne ${mealName[meal]} ke baad vitamin nahi li. ${n} reminder bheje, koi reply nahi. Ek call kar lo?`,
  alertSkipped: (meal: Meal, text: string) => `Reme: mummy ne aaj ${mealName[meal]} ke baad vitamin skip ki: "${text}"`,
};

// One row per dose per day, stored in SQLite (built into Node, no server needed),
// so reminders survive the laptop restarting.
import { DatabaseSync } from "node:sqlite";
import type { Meal } from "./config.ts";

export type Dose = {
  date: string; // YYYY-MM-DD, local time
  meal: Meal;
  status: "open" | "taken" | "skipped" | "missed";
  reminders: number; // nudges sent so far
  next_at: number | null; // ms timestamp of the next nudge
};

export function openStore(path = "reme.db") {
  const db = new DatabaseSync(path);
  db.exec(`
    CREATE TABLE IF NOT EXISTS doses (
      date TEXT NOT NULL,
      meal TEXT NOT NULL,
      status TEXT NOT NULL,
      reminders INTEGER NOT NULL DEFAULT 0,
      next_at INTEGER,
      PRIMARY KEY (date, meal)
    );
    CREATE TABLE IF NOT EXISTS log (
      at TEXT NOT NULL DEFAULT (datetime('now', 'localtime')),
      event TEXT NOT NULL,
      meal TEXT,
      detail TEXT
    );
  `);

  const getStmt = db.prepare("SELECT * FROM doses WHERE date = ? AND meal = ?");
  const saveStmt = db.prepare(`
    INSERT INTO doses (date, meal, status, reminders, next_at) VALUES (?, ?, ?, ?, ?)
    ON CONFLICT (date, meal) DO UPDATE SET status = excluded.status, reminders = excluded.reminders, next_at = excluded.next_at
  `);
  const openStmt = db.prepare("SELECT * FROM doses WHERE date = ? AND status = 'open'");
  const dueStmt = db.prepare("SELECT * FROM doses WHERE status = 'open' AND next_at <= ?");
  const logStmt = db.prepare("INSERT INTO log (event, meal, detail) VALUES (?, ?, ?)");

  return {
    get: (date: string, meal: Meal) => getStmt.get(date, meal) as Dose | undefined,
    save: (d: Dose) => void saveStmt.run(d.date, d.meal, d.status, d.reminders, d.next_at),
    open: (date: string) => openStmt.all(date) as Dose[],
    due: (nowMs: number) => dueStmt.all(nowMs) as Dose[],
    log: (event: string, meal: Meal | null = null, detail: string | null = null) => void logStmt.run(event, meal, detail),
  };
}

export type Store = ReturnType<typeof openStore>;

// The decision-making. Gemma tells us *what she said*; this decides *what to do*.
// No WhatsApp or Ollama here, so it can be tested with a fake clock (scripts/simulate.ts).
import { config, MEALS, type Meal } from "./config.ts";
import type { Dose, Store } from "./db.ts";
import type { Intent } from "./intent.ts";
import { say } from "./messages.ts";

export type Send = (to: "mummy" | "alert", text: string) => Promise<void>;

const MIN = 60_000;
const CHECK_IN_WINDOW = 2 * 60 * MIN; // don't ask about lunch at midnight if the laptop was asleep

export const dateKey = (d: Date) => d.toLocaleDateString("en-CA"); // YYYY-MM-DD

function mealAt(d: Date): Meal {
  const h = d.getHours();
  return h < 12 ? "breakfast" : h < 17 ? "lunch" : "dinner";
}

export class Reme {
  constructor(
    private db: Store,
    private send: Send,
    private now = () => new Date(),
  ) {}

  private dose(meal: Meal): Dose {
    const date = dateKey(this.now());
    return this.db.get(date, meal) ?? { date, meal, status: "open", reminders: 0, next_at: null };
  }

  // Which dose does "le li" / "baad mein" refer to? The latest open one today,
  // otherwise the most recent vitamin meal by the clock.
  private current(): Dose {
    const open = this.db.open(dateKey(this.now()));
    if (open.length) return open.sort((a, b) => MEALS.indexOf(b.meal) - MEALS.indexOf(a.meal))[0];
    const byClock = MEALS.indexOf(mealAt(this.now()));
    const meal = [...config.vitaminMeals].reverse().find((m) => MEALS.indexOf(m) <= byClock) ?? config.vitaminMeals[0];
    return this.dose(meal);
  }

  private after(min: number) {
    return this.now().getTime() + min * MIN;
  }

  async onMessage(i: Intent, text: string) {
    switch (i.intent) {
      case "meal_done": {
        const meal = i.meal && i.meal !== "unknown" ? i.meal : mealAt(this.now());
        this.db.log("meal_done", meal, text);
        if (!config.vitaminMeals.includes(meal)) return;
        const d = this.dose(meal);
        if (d.status === "taken") return this.send("mummy", say.alreadyTaken);
        this.db.save({ ...d, status: "open", reminders: 0, next_at: this.after(config.remindAfterMin) });
        return this.send("mummy", say.willRemind(config.remindAfterMin));
      }
      case "vitamin_taken": {
        const d = this.current();
        this.db.save({ ...d, status: "taken", next_at: null });
        this.db.log("taken", d.meal, text);
        return this.send("mummy", say.taken);
      }
      case "snooze": {
        const d = this.current();
        if (d.status === "taken") return;
        const min = i.snooze_minutes ?? config.remindAfterMin;
        this.db.save({ ...d, status: "open", next_at: this.after(min) });
        this.db.log("snooze", d.meal, text);
        return this.send("mummy", say.snoozed(min));
      }
      case "skip": {
        const d = this.current();
        this.db.save({ ...d, status: "skipped", next_at: null });
        this.db.log("skipped", d.meal, text);
        await this.send("mummy", say.skipped);
        return this.send("alert", say.alertSkipped(d.meal, text));
      }
      default:
        // Small talk is between her and you; Reme stays quiet.
        this.db.log("other", null, text);
    }
  }

  // Called every 30 seconds.
  async tick() {
    const now = this.now();

    for (const d of this.db.due(now.getTime())) {
      if (d.reminders >= config.maxReminders) {
        this.db.save({ ...d, status: "missed", next_at: null });
        this.db.log("missed", d.meal);
        await this.send("alert", say.alertMissed(d.meal, d.reminders));
        continue;
      }
      this.db.save({ ...d, reminders: d.reminders + 1, next_at: this.after(config.followUpMin) });
      this.db.log("reminder", d.meal);
      await this.send("mummy", d.reminders === 0 ? say.remind : say.followUp);
    }

    for (const meal of config.vitaminMeals) {
      const hm = config.checkIns[meal];
      if (!hm) continue;
      const at = new Date(now);
      at.setHours(hm[0], hm[1], 0, 0);
      const since = now.getTime() - at.getTime();
      if (since < 0 || since > CHECK_IN_WINDOW) continue;
      if (this.db.get(dateKey(now), meal)) continue; // she already told us something
      this.db.save({ date: dateKey(now), meal, status: "open", reminders: 1, next_at: this.after(config.followUpMin) });
      this.db.log("check_in", meal);
      await this.send("mummy", say.checkIn(meal));
    }
  }
}

// Run: pnpm simulate
// Plays out a whole day with a fake clock (real Gemma, no WhatsApp) so you can
// see every message Reme would send without waiting hours.
process.env.VITAMIN_MEALS = "lunch,dinner";

const { openStore } = await import("../src/db.ts");
const { parseMessage } = await import("../src/intent.ts");
const { Reme } = await import("../src/reme.ts");

let clock = new Date();
clock.setHours(13, 0, 0, 0);
const hhmm = () => clock.toTimeString().slice(0, 5);

const reme = new Reme(
  openStore(":memory:"),
  async (to, text) => console.log(`${hhmm()}  Reme → ${to === "mummy" ? "mummy" : "YOU  "}: ${text}`),
  () => clock,
);

// What mummy types, and when
const script: Record<string, string> = {
  "13:20": "haan beta khana kha liya",
  "13:37": "10 min ruko",
  "13:50": "le li",
  // dinner: she never replies, so you should get an alert
};

for (let m = 13 * 60; m <= 23 * 60; m++) {
  clock = new Date(clock);
  clock.setHours(Math.floor(m / 60), m % 60);
  const said = script[hhmm()];
  if (said) {
    console.log(`${hhmm()}  mummy: ${said}`);
    const intent = await parseMessage(said, clock);
    console.log(`        [gemma: ${intent.intent}${intent.snooze_minutes ? ` ${intent.snooze_minutes}m` : ""}]`);
    await reme.onMessage(intent, said);
  }
  await reme.tick();
}

// WhatsApp via Baileys: talks to WhatsApp Web's protocol directly (no browser).
// First run prints a QR code; scan it from WhatsApp > Linked devices.
import makeWASocket, { DisconnectReason, fetchLatestBaileysVersion, useMultiFileAuthState, type WAMessage } from "baileys";
import pino from "pino";
import qrcode from "qrcode-terminal";

const AUTH_DIR = "auth"; // login session; never commit this

export type Incoming = { from: string; text?: string; isVoice: boolean };

const phoneOf = (jid?: string | null) => (jid?.endsWith("@s.whatsapp.net") ? jid.split("@")[0].split(":")[0] : undefined);

